// Generate data/*.json from the English documents in docs/en/.
//
// CONTRACT
//   docs/en/*.md  is the single source of truth.
//   data/*.json   is derived. Never hand-edit a generated file — edit the document
//                 and re-run this script.
//   data/build.json is the ONE hand-written file here: it holds the verified build
//                 pin and the invariants the generator checks itself against.
//
// USAGE
//   node tools/build-data.mjs           # write data/*.json
//   node tools/build-data.mjs --check    # fail if data/*.json is stale (no writes)
//
// The --check mode is what CI and `npm run check:data` use. It is the drift guard:
// if a document changed and the data was not regenerated, it fails loudly instead of
// letting an agent read two contradictory sources.
import { readFileSync, writeFileSync, mkdirSync, readdirSync, existsSync } from "node:fs";
import { join, dirname, resolve, relative } from "node:path";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const DATA = join(root, "data");
const CHECK = process.argv.includes("--check");

const warnings = [];
const warn = (m) => warnings.push(m);

const readRaw = (rel) => readFileSync(join(root, rel), "utf8");
const readLines = (rel) => readRaw(rel).split(/\r?\n/);

/** Strip markdown decoration from a table cell, keeping the readable text. */
const stripMd = (s) =>
  String(s)
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/\*\*/g, "")
    .replace(/`/g, "")
    .replace(/\s+/g, " ")
    .trim();

/** Table cells use an em dash or a bare dash as "no value". */
const isDash = (s) => s === "" || /^[—–-]$/.test(s);
const orNull = (s) => (isDash(s) ? null : s);

function splitRow(line) {
  let s = line.trim();
  if (s.startsWith("|")) s = s.slice(1);
  if (s.endsWith("|")) s = s.slice(0, -1);
  return s.split(/(?<!\\)\|/).map((c) => c.replace(/\\\|/g, "|").trim());
}

/** Collect every markdown table in a document. */
function parseTables(src) {
  const out = [];
  for (let i = 0; i + 1 < src.length; i++) {
    if (!/^\s*\|/.test(src[i])) continue;
    if (!/^\s*\|[\s:|-]+\|\s*$/.test(src[i + 1])) continue;
    const header = splitRow(src[i]);
    const rows = [];
    let j = i + 2;
    for (; j < src.length && /^\s*\|/.test(src[j]); j++) {
      rows.push({ cells: splitRow(src[j]), line: j + 1 });
    }
    out.push({ header, rows, line: i + 1, endLine: j });
    i = j - 1;
  }
  return out;
}

/** Nearest heading of exactly the given level above a line (1-based). */
function headingBefore(src, line, level) {
  const re = new RegExp("^#{" + level + "}\\s+(.*)$");
  for (let i = line - 2; i >= 0; i--) {
    const m = re.exec(src[i]);
    if (m) return stripMd(m[1]);
  }
  return null;
}

/** "6. Mods and addons (General section)" -> "Mods and addons (General section)" */
const dropNumber = (h) => (h ? h.replace(/^\d+(\.\d+)*\.?\s*/, "").trim() : h);

/** Nearest heading of any level 2..4 above a line — needed where tables sit under ####. */
function nearestHeading(src, line) {
  for (let i = line - 2; i >= 0; i--) {
    const m = /^#{2,4}\s+(.*)$/.exec(src[i]);
    if (m) return stripMd(m[1]);
  }
  return null;
}

/** Nearest backticked SCR_* class name above a table — attributes it to a class. */
function classBefore(src, line, maxLook = 14) {
  for (let i = line - 2; i >= Math.max(0, line - 2 - maxLook); i--) {
    const m = /`(SCR_[A-Za-z]+)`/.exec(src[i]);
    if (m) return m[1];
  }
  return null;
}

/**
 * Split a parameter cell into its bare names.
 *   "`-config <file.json>`"       -> ["-config"]
 *   "`-AILimit` / `-aiLimit`"     -> ["-AILimit", "-aiLimit"]   (aliases of one parameter)
 *   "`-playerLimits \"<F>:<N>\"`" -> ["-playerLimits"]
 */
function paramNames(cell) {
  const names = [];
  for (const part of String(cell).split(/\s*\/\s*/)) {
    const tok = stripMd(part).split(/\s+/)[0] ?? "";
    if (/^-/.test(tok)) names.push(tok);
  }
  return names.length ? [...new Set(names)] : [stripMd(cell)];
}

const GUID_PATH = /^\{([0-9A-Fa-f]{16})\}(.+)$/;
const gitHash = (s) => createHash("sha256").update(s).digest("hex").slice(0, 16);

// ---------------------------------------------------------------- build pin
const BUILD_FILE = "data/build.json";
if (!existsSync(join(root, BUILD_FILE))) {
  console.error(`FATAL ${BUILD_FILE} is missing — it is the hand-written build pin.`);
  process.exit(2);
}
const pin = JSON.parse(readRaw(BUILD_FILE));
const GEN = (source) => ({
  $comment: `GENERATED by tools/build-data.mjs from ${source} — do not edit by hand`,
  build: pin.build,
  engine: pin.engine,
  source,
});

// ------------------------------------------------------- map codenames (MH §2.1)
function buildMapCodenames() {
  const rel = "docs/en/ArmaReforger_MissionHeader_EN.md";
  const src = readLines(rel);
  for (const t of parseTables(src)) {
    if (!/^Codename/i.test(stripMd(t.header[0]))) continue;
    const map = {};
    for (const r of t.rows) {
      const code = stripMd(r.cells[0]);
      const display = stripMd(r.cells[1] ?? "").replace(/\s*\(matches\)\s*/, "");
      if (code && display) map[code] = display;
    }
    return map;
  }
  warn("mapCodenames: no 'Codename' table found in the MissionHeader document");
  return {};
}

// ---------------------------------------------- scenario -> header class (MH §2)
function buildScenarioHeaderClasses() {
  const rel = "docs/en/ArmaReforger_MissionHeader_EN.md";
  const src = readLines(rel);
  const out = [];
  for (const t of parseTables(src)) {
    if (stripMd(t.header[0]) !== "Scenario file") continue;
    for (const r of t.rows) {
      const file = stripMd(r.cells[0]);
      const cls = stripMd(r.cells[1] ?? "");
      if (/^Missions\//.test(file) && /^SCR_/.test(cls)) {
        out.push({ scenarioFile: file, className: cls, docLine: r.line });
      }
    }
  }
  if (!out.length) warn("scenarioHeaderClasses: the documented mapping table was not found");
  return out;
}

// ------------------------------------------------------------ scenarios doc
function buildScenarios(codenames) {
  const rel = "docs/en/ArmaReforger_Scenarios_EN.md";
  const src = readLines(rel);
  const scenarios = [];
  const terrains = [];

  for (const t of parseTables(src)) {
    const h0 = stripMd(t.header[0]);
    const h1 = stripMd(t.header[1] ?? "");

    if (h0 === "Scenario" && /scenarioId/i.test(h1)) {
      const head = headingBefore(src, t.line, 2) ?? "";
      const section = /single-player/i.test(head) ? "singlePlayer" : "official";
      for (const r of t.rows) {
        const id = stripMd(r.cells[1]);
        const m = GUID_PATH.exec(id);
        if (!m) {
          warn(`scenarios: unparsable row at ${rel}:${r.line}: ${id}`);
          continue;
        }
        const rawName = stripMd(r.cells[0]);
        const codename = /\((Cain|Eden|Arland)\)/.exec(rawName)?.[1] ?? null;
        const name = rawName.replace(/\s*\((?:Cain|Eden|Arland)\)\s*$/, "").trim();
        if (codename && !codenames[codename]) {
          warn(`scenarios: codename '${codename}' is not in the map codename table`);
        }
        scenarios.push({
          scenarioId: id,
          guid: m[1].toUpperCase(),
          path: m[2],
          name,
          mapCodename: codename,
          map: codename ? codenames[codename] ?? codename : null,
          section,
          docLine: r.line,
        });
      }
    } else if (h0 === "Terrain") {
      for (const r of t.rows) {
        const id = stripMd(r.cells[1]);
        const m = GUID_PATH.exec(id);
        if (!m) {
          warn(`terrains: unparsable row at ${rel}:${r.line}: ${id}`);
          continue;
        }
        const rawName = stripMd(r.cells[0]);
        const fromPath = /^worlds\/([^/]+)\//.exec(m[2])?.[1] ?? null;
        const codename = /codename (\w+)/.exec(rawName)?.[1] ?? fromPath;
        const name = rawName
          .replace(/\s*\(codename \w+\)/, "")
          .replace(/\s*\(for a sub-scene\)/, "")
          .trim();
        terrains.push({
          guid: m[1].toUpperCase(),
          path: m[2],
          name,
          mapCodename: codename,
          map: codenames[codename] ?? codename,
          role: "terrainConfig",
          note: /for a sub-scene/.test(rawName) ? "empty world, for a sub-scene" : null,
          docLine: r.line,
        });
      }
    }
  }

  const official = scenarios.filter((s) => s.section === "official");
  const singlePlayer = scenarios.filter((s) => s.section === "singlePlayer");
  const inv = pin.invariants ?? {};
  if (inv["scenarios.official"] != null && official.length !== inv["scenarios.official"]) {
    warn(`scenarios: official count is ${official.length}, data/build.json says ${inv["scenarios.official"]}`);
  }
  if (inv["scenarios.singlePlayer"] != null && singlePlayer.length !== inv["scenarios.singlePlayer"]) {
    warn(`scenarios: single-player count is ${singlePlayer.length}, data/build.json says ${inv["scenarios.singlePlayer"]}`);
  }
  if (inv["terrains"] != null && terrains.length !== inv["terrains"]) {
    warn(`terrains: count is ${terrains.length}, data/build.json says ${inv["terrains"]}`);
  }

  const byGuid = {};
  for (const [i, s] of scenarios.entries()) byGuid[s.guid] = i;
  for (const [i, s] of terrains.entries()) byGuid[s.guid] ??= `terrain:${i}`;

  return {
    ...GEN(rel),
    counts: {
      official: official.length,
      singlePlayer: singlePlayer.length,
      total: scenarios.length,
      terrains: terrains.length,
    },
    mapCodenames: codenames,
    scenarioHeaderClasses: buildScenarioHeaderClasses(),
    byGuid,
    scenarios,
    terrains,
  };
}

// ------------------------------------------------------- startup params doc
function buildStartupParams() {
  const rel = "docs/en/ArmaReforger_StartupParams_EN.md";
  const src = readLines(rel);
  const params = [];
  const index = {};

  const push = (rec) => {
    const i = params.length;
    params.push(rec);
    for (const n of [rec.param, ...(rec.aliases ?? [])]) index[n] = i;
  };

  for (const t of parseTables(src)) {
    if (stripMd(t.header[0]) !== "Parameter") continue;
    const statusIdx = t.header.findIndex((h) => /1\.6\.0\.119/.test(h));
    if (statusIdx < 0) continue; // §7.1 summary table has no status column
    const valueIdx = t.header.findIndex((h) => stripMd(h) === "Value");
    const defaultIdx = t.header.findIndex((h) => stripMd(h) === "Default");
    const descIdx = t.header.findIndex((h) => stripMd(h) === "Description");
    const section = dropNumber(headingBefore(src, t.line, 2)) ?? "unknown";

    for (const r of t.rows) {
      const names = paramNames(r.cells[0]);
      if (!names.length) {
        warn(`startup-params: unparsable row at ${rel}:${r.line}`);
        continue;
      }
      const desc = descIdx >= 0 ? stripMd(r.cells[descIdx] ?? "") : "";
      const statusCell = stripMd(r.cells[statusIdx] ?? "").toLowerCase();
      push({
        param: names[0],
        aliases: names.slice(1),
        usage: stripMd(r.cells[0]),
        section,
        status: /absent|not in the binary/.test(statusCell) ? "absent" : "present",
        value: valueIdx >= 0 ? orNull(stripMd(r.cells[valueIdx] ?? "")) : null,
        default: defaultIdx >= 0 ? orNull(stripMd(r.cells[defaultIdx] ?? "")) : null,
        diagOnly: /\bDiag exe only\b/i.test(desc),
        scope: /Refers to the game executable|on the client/i.test(desc) ? "client" : "server",
        description: desc,
        docLine: r.line,
      });
    }
  }

  // §7.1 — the curated "do not use" list, with the wiki version tag.
  const absentIndex = [];
  for (const t of parseTables(src)) {
    if (stripMd(t.header[0]) !== "Parameter") continue;
    if (!/Version tag/i.test(stripMd(t.header[1] ?? ""))) continue;
    for (const r of t.rows) {
      const names = stripMd(r.cells[0]).split(",").map((s) => s.trim()).filter(Boolean);
      for (const n of names) absentIndex.push({ param: n, versionTag: orNull(stripMd(r.cells[1] ?? "")), docLine: r.line });
    }
  }

  // §7.2 — accepted on a real command line, yet no string in the binary.
  const special = [];
  const s72 = src.findIndex((l) => /^###\s+7\.2/.test(l));
  if (s72 >= 0) {
    for (const m of src[s72].matchAll(/`(-[A-Za-z-]+)`/g)) special.push(m[1]);
  } else {
    warn("startup-params: section 7.2 was not found");
  }

  const inTablesAbsent = params.filter((p) => p.status === "absent").map((p) => p.param);
  const union = [...new Set([...inTablesAbsent, ...absentIndex.map((a) => a.param), ...special])];

  for (const a of absentIndex) {
    const rec = index[a.param] != null ? params[index[a.param]] : null;
    if (!rec) warn(`startup-params: §7.1 lists ${a.param}, but it has no row in the reference tables`);
    else if (rec.status !== "absent") warn(`startup-params: ${a.param} is absent in §7.1 but marked present in the tables`);
  }
  for (const p of special) {
    const rec = index[p] != null ? params[index[p]] : null;
    if (!rec) warn(`startup-params: §7.2 names ${p}, but it has no row in the reference tables`);
  }

  // The document states its own totals in prose, in two places. Record both and let a
  // mismatch stay visible instead of being silently encoded.
  //   §0: "of the **70** parameters described in the wiki, **14 are absent** from ..."
  //   §7: "14 parameters from the wiki that are absent from the binary."
  const s0 = src.findIndex((l) => /^##\s+0\./.test(l));
  const prose = s0 >= 0 ? src.slice(s0, s0 + 40).join(" ") : "";
  const claim0 = /of the\s+\*\*(\d+)\*\*\s+parameters[\s\S]*?\*\*(\d+)\s+are absent\*\*/i.exec(prose);
  const s7 = src.findIndex((l) => /^##\s+7\./.test(l));
  const claim7 = s7 >= 0 ? /(\d+)\s+parameters from the wiki that are absent/i.exec(src.slice(s7, s7 + 6).join(" ")) : null;
  let docClaims = claim0
    ? { describedInWiki: Number(claim0[1]), absent: Number(claim0[2]), docLine: s0 + 1 }
    : null;
  if (!docClaims) warn("startup-params: could not parse the prose totals in §0");
  if (claim7) {
    if (docClaims) docClaims.absentSection7 = Number(claim7[1]);
    else docClaims = { absentSection7: Number(claim7[1]), docLine: s7 + 1 };
  }
  if (docClaims?.absentSection7 != null && docClaims.absent != null && docClaims.absent !== docClaims.absentSection7) {
    warn(`startup-params: §0 claims ${docClaims.absent} absent parameters while §7 claims ${docClaims.absentSection7}`);
  }

  if (docClaims && docClaims.absent !== union.length) {
    warn(
      `startup-params: the document claims ${docClaims.absent} absent parameters, ` +
        `but ${union.length} distinct names are actually marked absent ` +
        `(${inTablesAbsent.length} in the reference tables, ${absentIndex.length} in §7.1, ${special.length} in §7.2)`
    );
  }
  // The claim is about parameter NAMES: a row written as "-A` / `-B" contributes two names to
  // it, so the comparison is against the name count rather than the row count.
  const namesTotal = params.length + params.reduce((n, p) => n + (p.aliases?.length ?? 0), 0);
  if (docClaims && docClaims.describedInWiki !== namesTotal) {
    warn(
      `startup-params: the document claims ${docClaims.describedInWiki} parameter names, ` +
        `the reference tables produced ${namesTotal} names in ${params.length} entries`
    );
  }

  return {
    ...GEN(rel),
    counts: {
      total: params.length,
      namesTotal: params.length + params.reduce((n, p) => n + (p.aliases?.length ?? 0), 0),
      present: params.filter((p) => p.status === "present").length,
      absent: params.filter((p) => p.status === "absent").length,
      absentDistinct: union.length,
      diagOnly: params.filter((p) => p.diagOnly).length,
      clientScope: params.filter((p) => p.scope === "client").length,
    },
    docClaims,
    absentNames: union.sort(),
    acceptedButNotInBinary: special,
    index,
    params,
  };
}

// ---------------------------------------------------- server config key tables
function buildServerKeys() {
  const rel = "docs/en/ArmaReforger_ServerConfig_EN.md";
  const src = readLines(rel);
  const SECTION_PARENT = {
    "5.1": "root",
    "5.2": "a2s",
    "5.3": "rcon",
    "5.4": "game",
    "5.4.1": "game.mods[]",
    "5.5": "game.gameProperties",
    "5.6": "operating",
  };
  const keys = [];
  const undocumented = [];

  for (const t of parseTables(src)) {
    if (stripMd(t.header[0]) !== "Key") continue;
    const head = nearestHeading(src, t.line) ?? "";
    const num = /^(\d+\.\d+(?:\.\d+)?)/.exec(head)?.[1] ?? null;
    const parent = num ? SECTION_PARENT[num] ?? null : null;
    if (!parent) {
      warn(`server-keys: table at ${rel}:${t.line} has no known section heading ("${head}")`);
      continue;
    }
    const typeIdx = t.header.findIndex((h) => /^Type/i.test(stripMd(h)));
    const defIdx = t.header.findIndex((h) => stripMd(h) === "Default");
    const srcIdx = t.header.findIndex((h) => stripMd(h) === "Source");
    const descIdx = t.header.findIndex((h) => /Description|What it does/i.test(stripMd(h)));

    for (const r of t.rows) {
      let key = stripMd(r.cells[0]);
      if (!key) continue;
      // A dotted cell such as `joinQueue.maxSize` names a nested field, not a literal key.
      let keyParent = parent;
      if (key.includes(".")) {
        const parts = key.split(".");
        key = parts.pop();
        keyParent = `${parent}.${parts.join(".")}`;
      }
      const description = descIdx >= 0 ? stripMd(r.cells[descIdx] ?? "") : "";
      // Cells that only say "Same." inherit the previous row's undocumented flag.
      const previous = keys[keys.length - 1];
      const undocumented = /not publicly documented|not documented/i.test(description)
        ? true
        : /^same\.?$/i.test(description) && previous?.parent === keyParent
          ? previous.undocumented
          : false;
      keys.push({
        key,
        parent: keyParent,
        type: typeIdx >= 0 ? orNull(stripMd(r.cells[typeIdx] ?? "")) : null,
        default: defIdx >= 0 ? orNull(stripMd(r.cells[defIdx] ?? "")) : null,
        source: srcIdx >= 0 ? (/\[binary\]/.test(r.cells[srcIdx]) ? "binary" : "wiki") : null,
        undocumented,
        description,
        docLine: r.line,
      });
    }
  }

  // §5.7 — undocumented keys listed in a fenced block.
  const s57 = src.findIndex((l) => /^###\s+5\.7/.test(l));
  if (s57 >= 0) {
    let inFence = false;
    for (let i = s57; i < src.length; i++) {
      if (/^```/.test(src[i])) {
        if (inFence) break;
        inFence = true;
        continue;
      }
      if (inFence) for (const k of src[i].trim().split(/\s+/).filter(Boolean)) undocumented.push(k);
    }
  } else {
    warn("server-keys: section 5.7 was not found");
  }

  const inv = pin.invariants ?? {};
  if (inv["serverKeys"] != null && keys.length !== inv["serverKeys"]) {
    warn(`server-keys: ${keys.length} keys parsed, data/build.json says ${inv["serverKeys"]}`);
  }

  return {
    ...GEN(rel),
    counts: {
      total: keys.length,
      wiki: keys.filter((k) => k.source === "wiki").length,
      binary: keys.filter((k) => k.source === "binary").length,
      undocumented: keys.filter((k) => k.undocumented).length,
      undocumentedSection57: undocumented.length,
    },
    undocumentedKeys: [...new Set(undocumented)].sort(),
    keys,
  };
}

// -------------------------------------------------- mission header field tables
function buildMissionHeaderFields() {
  const rel = "docs/en/ArmaReforger_MissionHeader_EN.md";
  const src = readLines(rel);
  const fields = [];
  const nestedTypes = [];
  const ranks = [];

  for (const t of parseTables(src)) {
    const h0 = stripMd(t.header[0]);

    // §3.2 — the rank enum: | Value | Member | Note |
    if (h0 === "Value" && /^Member$/i.test(stripMd(t.header[1] ?? ""))) {
      for (const r of t.rows) {
        const value = Number(stripMd(r.cells[0]));
        const member = stripMd(r.cells[1]);
        if (!Number.isFinite(value) || !member) continue;
        ranks.push({
          value,
          member,
          note: orNull(stripMd(r.cells[2] ?? "")),
          docLine: r.line,
        });
      }
      continue;
    }

    if (h0 !== "Key") continue;
    const className = classBefore(src, t.line);
    if (!className) {
      warn(`mission-header-fields: table at ${rel}:${t.line} could not be attributed to a class`);
      continue;
    }
    const typeIdx = t.header.findIndex((h) => stripMd(h) === "Type");
    const defIdx = t.header.findIndex((h) => stripMd(h) === "Default");
    const descIdx = t.header.findIndex((h) => /Description|What it does/i.test(stripMd(h)));
    const topLevel = /^SCR_MissionHeader/.test(className);

    for (const r of t.rows) {
      const key = stripMd(r.cells[0]);
      if (!/^m_/.test(key)) continue;
      const rec = {
        key,
        className,
        type: typeIdx >= 0 ? orNull(stripMd(r.cells[typeIdx] ?? "")) : null,
        default: defIdx >= 0 ? orNull(stripMd(r.cells[defIdx] ?? "")) : null,
        description: descIdx >= 0 ? stripMd(r.cells[descIdx] ?? "") : "",
        docLine: r.line,
      };
      (topLevel ? fields : nestedTypes).push(rec);
    }
  }

  if (!ranks.length) warn("mission-header-fields: the SCR_ECharacterRank table was not found");
  const campaign = fields.filter((f) => f.className === "SCR_MissionHeaderCampaign");
  const base = fields.filter((f) => f.className === "SCR_MissionHeader");
  const inv = pin.invariants ?? {};
  if (inv["missionHeader.baseFields"] != null && base.length !== inv["missionHeader.baseFields"]) {
    warn(`mission-header-fields: ${base.length} base fields, data/build.json says ${inv["missionHeader.baseFields"]}`);
  }
  if (inv["missionHeader.campaignFields"] != null && campaign.length !== inv["missionHeader.campaignFields"]) {
    warn(`mission-header-fields: ${campaign.length} campaign fields, data/build.json says ${inv["missionHeader.campaignFields"]}`);
  }

  const allowedByClass = {};
  for (const f of fields) (allowedByClass[f.className] ??= []).push(f.key);

  return {
    ...GEN(rel),
    counts: {
      total: fields.length,
      base: base.length,
      campaign: campaign.length,
      nestedTypeFields: nestedTypes.length,
      ranks: ranks.length,
    },
    // Which top-level missionHeader keys each scenario header class accepts.
    // A key from a foreign class is silently ignored by the server.
    allowedByClass,
    classHierarchy: ["SCR_MissionHeader", "SCR_MissionHeaderCampaign", "SCR_MissionHeaderCombatOps"],
    ranks,
    fields,
    nestedTypes,
  };
}

// --------------------------------------------------------------- doc manifest
function walkMd(dir, out = []) {
  for (const e of readdirSync(join(root, dir), { withFileTypes: true })) {
    if (e.name.startsWith(".") || e.name === "node_modules") continue;
    const rel = `${dir}/${e.name}`;
    if (e.isDirectory()) walkMd(rel, out);
    else if (e.name.endsWith(".md")) out.push(rel);
  }
  return out;
}

function buildManifest() {
  const documents = [];
  for (const rel of walkMd("docs").sort()) {
    const text = readRaw(rel);
    const base = rel.split("/").pop();
    documents.push({
      path: rel,
      language: /_EN\.md$/.test(base) ? "en" : /_RU\.md$/.test(base) ? "ru" : null,
      lines: text.split(/\r?\n/).length,
      bytes: Buffer.byteLength(text, "utf8"),
      buildPin: /(\d+\.\d+\.\d+\.\d+)/.exec(text)?.[1] ?? null,
      sha256_16: gitHash(text),
      pair: base.replace(/_(EN|RU)\.md$/, "") || null,
    });
  }

  const skills = [];
  const skillsDir = join(root, "skills");
  if (existsSync(skillsDir)) {
    for (const d of readdirSync(skillsDir, { withFileTypes: true })) {
      if (!d.isDirectory()) continue;
      const rel = `skills/${d.name}/SKILL.md`;
      if (!existsSync(join(root, rel))) {
        warn(`manifest: ${d.name}/SKILL.md is missing`);
        continue;
      }
      const text = readRaw(rel);
      const fm = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text)?.[1] ?? "";
      skills.push({
        name: /^name:\s*(.+)$/m.exec(fm)?.[1]?.trim() ?? null,
        path: rel,
        description: /^description:\s*(.+)$/m.exec(fm)?.[1]?.trim() ?? null,
        lines: text.split(/\r?\n/).length,
        bytes: Buffer.byteLength(text, "utf8"),
        sha256_16: gitHash(text),
      });
    }
  }

  const pairs = {};
  for (const d of documents) {
    if (!d.pair) continue;
    (pairs[d.pair] ??= {})[d.language] = d.path;
  }

  return {
    ...GEN("docs/ and skills/ (file inventory)"),
    documents,
    skills,
    pairs,
  };
}

// ------------------------------------------------------------------- driver
const codenames = buildMapCodenames();
const outputs = {
  "data/scenarios.json": buildScenarios(codenames),
  "data/startup-params.json": buildStartupParams(),
  "data/server-keys.json": buildServerKeys(),
  "data/mission-header-fields.json": buildMissionHeaderFields(),
  "data/manifest.json": buildManifest(),
};

mkdirSync(DATA, { recursive: true });
let stale = 0;
for (const [rel, obj] of Object.entries(outputs)) {
  const serialized = JSON.stringify(obj, null, 2) + "\n";
  const abs = join(root, rel);
  const existing = existsSync(abs) ? readFileSync(abs, "utf8") : null;
  const same = existing !== null && existing.replace(/\r\n/g, "\n") === serialized;

  if (CHECK) {
    if (same) {
      console.log(`OK    ${rel}`);
    } else {
      stale++;
      console.log(`STALE ${rel}`);
      if (existing === null) {
        console.log("      file does not exist — run: npm run build:data");
      } else {
        const a = existing.replace(/\r\n/g, "\n").split("\n");
        const b = serialized.split("\n");
        const at = a.findIndex((l, i) => l !== b[i]);
        console.log(`      first difference at line ${at + 1}:`);
        console.log(`        on disk: ${(a[at] ?? "<eof>").slice(0, 120)}`);
        console.log(`        rebuilt: ${(b[at] ?? "<eof>").slice(0, 120)}`);
      }
    }
  } else {
    writeFileSync(abs, serialized);
    console.log(`${same ? "=   " : "WROTE"} ${rel}`);
  }
}

for (const w of warnings) console.log(`WARN  ${w}`);
console.log(
  `\n${CHECK ? (stale ? `${stale} generated file(s) are stale` : "data/ is in sync with docs/en/") : "data/ regenerated"}` +
    (warnings.length ? `, ${warnings.length} warning(s)` : "")
);

if (CHECK && stale) process.exit(1);
